      "path": "integrations/dsh/src/reme/client.ts",
      "content": "import type {\n  AutoMemoryOptions,\n  DreamOptions,\n  ReMeClientConfig,\n  ReMeHealth,\n  ReMeHealthResult,\n  ReMeFileListingResult,\n  ReMeFileResult,\n  ReMeMemoryStatus,\n  ReMeMessage,\n  ReMeResult,\n  ReMeStatusResult,\n  SearchOptions,\n} from \"./types.js\";\n\nimport { safeError, validEndpoint } from \"../endpoint.js\";\n\ninterface ReMeResponseBody {\n  success?: boolean;\n  answer?: unknown;\n  metadata?: Record<string, unknown>;\n  detail?: unknown;\n}\n\nexport class ReMeClient {\n  private readonly configSource: () => ReMeClientConfig;\n\n  constructor(config: ReMeClientConfig | (() => ReMeClientConfig)) {\n    this.configSource = typeof config === \"function\" ? config : () => config;\n  }\n\n  async search(\n    query: string,\n    options: SearchOptions = {},\n  ): Promise<ReMeResult> {\n    const config = this.configSource();\n    return this.request(\n      \"search\",\n      {\n        query,\n        limit: options.limit,\n        min_score: options.minScore,\n      },\n      config,\n      config.requestTimeoutMs,\n      options.signal,\n    );\n  }\n\n  async autoMemory(\n    messages: ReMeMessage[],\n    sessionId: string,\n    options: AutoMemoryOptions = {},\n  ): Promise<ReMeResult> {\n    const base = this.configSource();\n    const endpoint = options.endpoint || base.endpoint;\n    // A recovered batch keeps the endpoint it was queued for. The token is\n    // scoped to the *configured* endpoint, so it must not ride along when the\n    // batch goes somewhere else.\n    const config: ReMeClientConfig = {\n      ...base,\n      endpoint,\n      ...(endpoint === base.endpoint ? {} : { authToken: \"\" }),\n    };\n    return this.request(\n      \"auto_memory\",\n      {\n        messages,\n        session_id: sessionId,\n        memory_hint: options.memoryHint || \"\",\n        date: options.date || \"\",\n        ...(options.requestId ? { request_id: options.requestId } : {}),\n      },\n      config,\n      config.backgroundTimeoutMs,\n      options.signal,\n    );\n  }\n\n  async autoDream(options: DreamOptions = {}): Promise<ReMeResult> {\n    const config = this.configSource();\n    return this.request(\n      \"auto_dream\",\n      {\n        date: options.date || \"\",\n        hint: options.hint || \"\",\n      },\n      config,\n      config.backgroundTimeoutMs,\n      options.signal,\n    );\n  }\n\n  async healthCheck(\n    options: { signal?: AbortSignal } = {},\n  ): Promise<ReMeHealthResult> {\n    const config = this.configSource();\n    const result = await this.request(\n      \"health_check\",\n      {},\n      config,\n      config.requestTimeoutMs,\n      options.signal,\n    );\n    return {\n      ...result,\n      health: healthFrom(result.metadata?.health),\n    };\n  }\n\n  async status(\n    options: { signal?: AbortSignal } = {},\n  ): Promise<ReMeStatusResult> {\n    const config = this.configSource();\n    const result = await this.request(\n      \"status\",\n      {},\n      config,\n      config.requestTimeoutMs,\n      options.signal,\n    );\n    return {\n      ...result,\n      memory: memoryFrom(result.metadata?.status),\n    };\n  }\n\n  async appConfig(options: { signal?: AbortSignal } = {}): Promise<ReMeResult> {\n    const config = this.configSource();\n    return this.request(\n      \"app_config\",\n      {},\n      config,\n      config.requestTimeoutMs,\n      options.signal,\n    );\n  }\n\n  async listFiles(\n    path: string,\n    options: { limit?: number; signal?: AbortSignal } = {},\n  ): Promise<ReMeFileListingResult> {\n    const config = this.configSource();\n    const limit = options.limit ?? 5000;\n    const result = await this.request(\n      \"list\",\n      {\n        path,\n        recursive: true,\n        sort_by: \"mtime\",\n        extensions: [\"md\", \"markdown\", \"txt\", \"yaml\", \"yml\"],\n        limit,\n      },\n      config,\n      config.requestTimeoutMs,\n      options.signal,\n    );\n    const items = result.metadata?.items;\n    const files = Array.isArray(items)\n      ? items.filter((item): item is string => typeof item === \"string\")\n      : [];\n    return { ...result, files, limited: files.length >= limit };\n  }\n\n  async loadFile(\n    path: string,\n    options: { signal?: AbortSignal } = {},\n  ): Promise<ReMeFileResult> {\n    const config = this.configSource();\n    const result = await this.request(\n      \"load\",\n      { path },\n      config,\n      config.requestTimeoutMs,\n      options.signal,\n    );\n    return {\n      ...result,\n      content: result.ok ? String(result.answer ?? \"\") : undefined,\n      path:\n        typeof result.metadata?.path === \"string\"\n          ? result.metadata.path\n          : undefined,\n      mtime:\n        typeof result.metadata?.mtime === \"string\"\n          ? result.metadata.mtime\n          : undefined,\n    };\n  }\n\n  private async request(\n    job: string,\n    payload: Record<string, unknown>,\n    config: ReMeClientConfig,\n    timeoutMs: number,\n    externalSignal?: AbortSignal,\n  ): Promise<ReMeResult> {\n    const controller = new AbortController();\n    const timer = setTimeout(() => controller.abort(), timeoutMs);\n    const signal = externalSignal\n      ? AbortSignal.any([externalSignal, controller.signal])\n      : controller.signal;\n    try {\n      if (!validEndpoint(config.endpoint))\n        throw new TypeError(\n          \"Invalid ReMe endpoint: credentials, query, and fragment are unsupported\",\n        );\n      const headers: Record<string, string> = {\n        \"Content-Type\": \"application/json\",\n      };\n      // The token belongs to the endpoint it was configured for, so it is sent\n      // here and not on any other request this plugin makes.\n      if (config.authToken)\n        headers.Authorization = `Bearer ${config.authToken}`;\n      const response = await fetch(`${config.endpoint}/${job}`, {\n        method: \"POST\",\n        headers,\n        body: JSON.stringify(payload),\n        signal,\n      });\n      const body = (await response\n        .json()\n        .catch(() => ({}))) as ReMeResponseBody;\n      const ok = response.ok && body.success !== false;\n      return {\n        ok,\n        status: response.status,\n        answer: body.answer ?? \"\",\n        metadata: body.metadata ?? {},\n        error: ok\n          ? \"\"\n          : safeError(body.answer || body.detail || `HTTP ${response.status}`),\n      };\n    } catch (error) {\n      return {\n        ok: false,\n        status: 0,\n        answer: \"\",\n        metadata: {},\n        error: safeError(error),\n      };\n    } finally {\n      clearTimeout(timer);\n    }\n  }\n}\n\nfunction healthFrom(value: unknown): ReMeHealth | undefined {\n  if (\n    !isRecord(value) ||\n    typeof value.version !== \"string\" ||\n    typeof value.healthy !== \"boolean\"\n  )\n    return undefined;\n  if (!isRecord(value.components)) return undefined;\n  return value as unknown as ReMeHealth;\n}\n\nfunction memoryFrom(value: unknown): ReMeMemoryStatus | undefined {\n  if (!isRecord(value) || !isRecord(value.memory)) return undefined;\n  const memory = value.memory;\n  if (\n    typeof memory.process_rss_bytes !== \"number\" ||\n    typeof memory.process_rss !== \"string\"\n  )\n    return undefined;\n  return memory as unknown as ReMeMemoryStatus;\n}\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === \"object\" && value !== null && !Array.isArray(value);\n}\n"
    },
